-- TRENERKI Academy · Uprawnienia Świętego Mikołaja · redakcja 2026-11-11
-- Zachowuje identyfikatory lekcji, kolejność, indeksy poprawnych odpowiedzi i projekt kursu.
-- Oryginalne materiały zapisano osobno. Warunek updated_at chroni nowszą redakcję.

DO $santa_update$
DECLARE
  item jsonb;
  current_lesson public.ta_lessons%ROWTYPE;
  lesson_material jsonb;
  patches jsonb := $santa_data$
[{"lesson_no":0,"updated_at":"2026-11-10 13:31:31.964815+00","patch":{"learning":{"task":"Przećwicz warianty udziału z obserwatorem. Zapisz zdanie powitania, zdanie dla opiekuna i sygnał, po którym kończysz zachęcanie.","intro":"Po tej lekcji przygotujesz powitanie, które daje dziecku realny wybór i pozwala mu uczestniczyć na własnych zasadach.","correct":0,"example":"Jeśli dziecko chce popatrzeć z kanapy, można do niego spokojnie pomachać. Paczkę może odebrać opiekun albo dziecko później.","options":["Przywitam dziecko z miejsca i zaproponuję, że paczkę odbierze opiekun lub ono samo, kiedy zechce.","Poproszę dziadka, żeby przyprowadził dziecko do fotela, a potem zapytam, czy jest mu tam wygodnie.","Uklęknę tuż obok kanapy i jeszcze raz poproszę, żeby dziecko podeszło do fotela.","Zachowam paczkę do momentu, gdy dziecko zgodzi się podejść na krótkie powitanie."],"feedback":["Sześciolatek wybrał obserwowanie z kanapy. Powitanie z tego miejsca pozwala uszanować decyzję i nadal włączyć dziecko w wydarzenie.","Sprawdzasz komfort dopiero po przemieszczeniu dziecka. Jego wybór obowiązuje od powitania.","Zbliżenie się zmniejsza dystans, który dziecko już wybrało.","Paczka staje się nagrodą za zgodę na kontakt. Dziecko ma ją otrzymać przy każdym sposobie udziału."],"question":"Jak odpowiesz, żeby dziecko zachowało wybór i mogło odebrać paczkę?","situation":"Podczas domowej wizyty sześciolatek patrzy z kanapy i mówi: „Stąd cię dobrze widzę”. Dziadek zaprasza go do fotela Mikołaja.","topic_kind":"case_from_existing_curriculum","explanation":"Sześciolatek wybrał obserwowanie z kanapy. Powitanie z tego miejsca pozwala uszanować decyzję i nadal włączyć dziecko w wydarzenie.","quiz_version":4,"quality_review":"requires_subject_expert_review"},"sections":[{"heading":"Udział na własnych zasadach","text":"Animator zaprasza, dziecko wybiera. Może podejść, pomachać z miejsca, zostać obok opiekuna lub poprosić go o odebranie paczki. Zaproszenie działa, gdy wszystkie te możliwości są traktowane równie życzliwie. Jeśli dziecko milczy, zamiera lub odwraca głowę, zatrzymaj się i daj mu przestrzeń. Za chwilę możesz spokojnie zaprosić kolejną osobę."},{"heading":"Uzgodnij zasady z gospodarzem","text":"Przed wydarzeniem ustal z opiekunem, gdzie dziecko ma swobodę obserwowania i kto odbierze paczkę, jeśli zostanie na miejscu. Jeśli dorosły zachęca do podejścia, uznaj jego intencję i powiedz, jak zachowasz wybór dziecka. W razie potrzeby zwróć się bezpośrednio do dziecka na spokojnym poziomie głosu."},{"heading":"Przykład z rodzinnego spotkania","text":"Babcia zapowiada wspólne zdjęcie. Dziecko cofa się pod ścianę. Animator mówi do całej grupy: „Można się przywitać także z miejsca”. Do babci zwraca się ciszej: „Zróbmy przerwę na zdjęcia. Pani może chwilę posiedzieć obok wnuczki”. Paczka nadal czeka na swoją właścicielkę."},{"heading":"Pracownia. Trzy sposoby uczestnictwa","text":"Narysuj ustawienie wejścia, miejsca dla opiekuna i miejsca dla obserwatora. Odegraj trzy rundy z drugą osobą: dziecko z ochotą podchodzi, dziecko milczy, dorosły ponawia zachętę po odmowie. Zamieńcie się rolami. Obserwator zapisuje każde ponowione polecenie, krok w stronę cofającego się dziecka i moment, w którym opiekun może pomóc. Po uwagach skróć powitanie do dwóch zdań i powtórz wszystkie rundy."},{"heading":"Sprawdź wynik po wykonaniu","text":"W każdej rundzie dziecko miało dostęp do tej samej paczki, mogło obserwować i mogło się wycofać. Twoja odpowiedź do dorosłego podtrzymała te zasady. Sygnał wycofania zakończył zapraszanie."}],"practice":{"title":"Rola i zgoda","minutes":55,"visual":{"title":"Trzy sposoby wzięcia udziału","kind":"comparison","entries":[{"label":"Podejście","detail":"Dziecko samo wybiera moment i odległość."},{"label":"Powitanie z miejsca","detail":"Wystarczy pomachać lub po prostu obserwować."},{"label":"Odbiór przez opiekuna","detail":"Paczka pozostaje dostępna przy każdej decyzji."}]}},"curiosity":"Krótka pauza po powitaniu pozwala dziecku samemu zdecydować, czy chce odpowiedzieć słowem, gestem czy tylko popatrzeć.","content_revision":"2026-11-11"}},
{"lesson_no":1,"updated_at":"2026-11-11 08:50:31.433497+00","patch":{"learning":{"task":"Ułóż tabelę prób z polami „element”, „co utrudniało ruch” i „jak sprawdziłem poprawkę”. Wykonaj cztery ruchy z grafiki.","intro":"Sprawdzisz kostium w ruchu i dostosujesz sposób wniesienia paczek do miejsca wizyty.","correct":1,"example":"Jeżeli przez brodę trudno mówić, popraw jej mocowanie i powtórz próbę rozmowy w pełnym stroju. Pomocnik może wcześniej wnieść paczki.","options":["Przejdę trasę bez stroju, a paczki będę wręczać dwiema dłońmi, żeby się nie wysunęły.","Poprawię lub wymienię brodę i rękawice, sprawdzę trasę w stroju, a prezenty wniesie pomocnik.","Podwinę rękawy i powierzę worek pomocnikowi, a brodę będę poprawiać przed każdą wypowiedzią.","Odłożę rękawice do czasu wręczania i wejdę w pozostałej części stroju bez drugiej próby."],"feedback":["Próba bez stroju pomija ograniczenia widoczności, ruchu i mówienia.","Próba w ostatecznym stroju pozwala wychwycić kilka ograniczeń naraz. Oddzielenie wejścia animatora od transportu paczek ułatwia bezpieczny ruch.","Pomoc przy worku jest sensowna. Broda nadal przeszkadza w swobodnym mówieniu i wymaga użycia dłoni.","Ułatwiasz chwyt, ale nie sprawdzasz poprawy widoczności, głosu ani przejścia w pełnym stroju."],"question":"Jak przygotujesz bezpieczne wejście i wręczanie paczek?","situation":"Na próbie broda wchodzi w usta, kiedy animator mówi, a rękawice ślizgają się po papierze. Do świetlicy prowadzą trzy stopnie.","topic_kind":"case_from_existing_curriculum","explanation":"Próba w ostatecznym stroju pozwala wychwycić kilka ograniczeń naraz. Oddzielenie wejścia animatora od transportu paczek ułatwia bezpieczny ruch.","quiz_version":4,"quality_review":"requires_subject_expert_review"},"sections":[{"heading":"Sprawność w pełnym kostiumie","text":"Czapkę, brodę, buty i rękawice sprawdzaj razem. To, co pasuje w pozycji stojącej, może zsunąć się przy obrocie, zasłonić usta albo zasłaniać podłogę przy schylaniu. Ustaw lustro lub poproś pomocnika o obserwację. Wypowiedz dwa zdania, obróć głowę w obie strony i spróbuj pewnie podnieść lekką paczkę."},{"heading":"Droga między wejściem a grupą","text":"Przejdź zaplanowaną trasę w dobrym świetle, najpierw z wolnymi rękami. Obejrzyj progi, podwinięte dywaniki i miejsce, w którym rękaw może zaczepić o klamkę. Ustal, kto wniesie prezenty. Przy schodach i ograniczonej widoczności pomocnik może ustawić paczki wcześniej, a animator skorzystać z dostępnej poręczy. Zaplanuj odległość kostiumu od otwartego ognia i gorących dekoracji."},{"heading":"Przykład z wizyty w świetlicy","text":"Broda dobrze wygląda na zdjęciu, ale zsuwa się na usta przy głębszym ukłonie. Animator poprawia mocowanie, ponownie rozmawia z pomocnikiem z drugiego końca sali i próbuje podejść do stolika. Jeżeli wciąż musi odgarniać brodę dłonią, zmienia ją przed wejściem."},{"heading":"Sprawdź wynik po wykonaniu","text":"Masz zapis czterech prób. Podczas każdej widzisz trasę, wypowiadasz zdania swobodnie, stawiasz pewne kroki i odkładasz paczkę bez poprawiania kostiumu. Po zmianie stroju powtórz próbę, która wcześniej się nie powiodła."}],"practice":{"title":"Próba kostiumu w czterech ruchach","visual":{"title":"Próba kostiumu w czterech ruchach","kind":"flow","entries":[{"label":"Rozejrzyj się","detail":"Sprawdź podłogę i widok po obróceniu głowy."},{"label":"Powiedz dwa zdania","detail":"Sprawdź swobodę oddechu i słyszalność głosu."},{"label":"Przejdź trasę","detail":"Sprawdź buty, podwinięte tkaniny i progi."},{"label":"Odłóż paczkę","detail":"Sprawdź chwyt i wybierz pomoc przy ciężkim worku."}]}},"curiosity":"Sprawdź brodę także podczas ukłonu. Zmiana pozycji może przesunąć mocowanie i zasłonić usta, choć w lustrze na stojąco wszystko wygląda dobrze.","content_revision":"2026-11-11"}},
{"lesson_no":2,"updated_at":"2026-11-11 08:50:31.433497+00","patch":{"learning":{"task":"Zamień trzy pytania oceniające na krótkie zaproszenia. Przećwicz każde z odpowiedzią słowną, gestem i bez odpowiedzi.","intro":"Przećwicz krótką rozmowę, która pozwala dziecku coś opowiedzieć lub pozostać słuchaczem.","correct":1,"example":"Zamiast pytać o ostatnią uwagę w dzienniczku, można zaprosić do pokazania ulubionej ozdoby. Jeśli dziecko nie odpowiada, wystarczy spokojnie je pozdrowić.","options":["Poproszę o jedno krótkie zdanie przeprosin, żeby zmniejszyć stres przed grupą.","Zmienię temat na neutralne powitanie i wręczę paczkę bez oczekiwania odpowiedzi.","Poproszę opiekuna, żeby opowiedział o zdarzeniu za dziecko, a potem wręczę paczkę.","Zaproponuję przeprosiny szeptem do mojego ucha i późniejsze wręczenie prezentu."],"feedback":["Krótsza wypowiedź nadal stawia publiczne przeprosiny jako warunek.","Paczka i udział w zabawie są dostępne także bez publicznej wypowiedzi. Neutralne powitanie pozwala zamknąć niezręczny wątek bez zawstydzania.","Wyręczenie dziecka w odpowiedzi nadal ujawnia prywatną sprawę całej grupie.","Prywatniejszy ton nie usuwa presji. Zachowaj też przestrzeń osobistą dziecka."],"question":"Jak poprowadzisz dalszą rozmowę w obecności grupy?","situation":"Podczas rozdawania paczek opiekun mówi: „Zanim dostanie prezent, niech powie, za co przeprasza”. Dziecko zaciska usta i spuszcza wzrok.","topic_kind":"case_from_existing_curriculum","explanation":"Paczka i udział w zabawie są dostępne także bez publicznej wypowiedzi. Neutralne powitanie pozwala zamknąć niezręczny wątek bez zawstydzania.","quiz_version":4,"quality_review":"requires_subject_expert_review"},"sections":[{"heading":"Zacznij od rozmowy dostępnej dla dziecka","text":"Zamiast pytać o ocenę zachowania, zaproś do tematu z otoczenia: lampki, ulubiona zabawa, piosenka lub obrazek. Użyj jednego krótkiego zdania. Zostaw chwilę ciszy, bo dziecko może potrzebować czasu na reakcję. Gest, uśmiech lub brak odpowiedzi są możliwym zakończeniem powitania."},{"heading":"Ogranicz publiczne pytania","text":"Rozmowę o zdrowiu, szkole, nieobecnych bliskich czy trudnościach w domu zostaw na prywatny kontakt z zaufanym dorosłym. Jeśli opiekun podpowiada, żeby publicznie rozliczyć zachowanie, możesz zwrócić się do grupy neutralnym zdaniem o zabawie. Utrzymaj ciepły ton wobec opiekuna i dziecka."},{"heading":"Przykład z urodzin w grudniu","text":"Rodzic mówi do Mikołaja: „Niech pan go zapyta, co ostatnio nabroił”. Animator odpowiada: „Dziś możemy się przywitać po swojemu. Możesz pokazać, którą ozdobę najbardziej lubisz”. Gdy dziecko patrzy na choinkę i milczy, animator daje mu chwilę i przechodzi dalej bez komentarza."},{"heading":"Pracownia. Komunikaty w trzech miejscach","text":"Wymyśl po jednym krótkim powitaniu do mieszkania, przedszkola i głośnej sali. Następnie odegraj z partnerem rozmowę, gdy dorosły prosi o ocenę zachowania, dziecko odpowiada gestem i dziecko milczy. W każdej scenie przetestuj dwie różne reakcje. Obserwator zapisuje, ile pytań zadałeś i które zdanie stwarzało nacisk. Zmień po jednym sformułowaniu i nagraj dla siebie próbę bez udziału dzieci."},{"heading":"Sprawdź wynik po wykonaniu","text":"W każdej scenie dziecko dostało jedno proste zaproszenie. Czas na odpowiedź wynikał z jego reakcji. Twoja dalsza odpowiedź nie zawierała oceny zachowania ani komentarza do milczenia."}],"practice":{"title":"Komunikaty i przygotowanie","minutes":65,"visual":{"title":"Zdania, które zostawiają wybór","kind":"comparison","entries":[{"label":"Zaproszenie","detail":"„Jeśli masz ochotę, pokaż mi ulubioną ozdobę”."},{"label":"Chwila na reakcję","detail":"Odczekaj spokojnie po jednym pytaniu."},{"label":"Zakończenie","detail":"„Dziękuję, miło było się przywitać” wystarczy także po ciszy."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":3,"updated_at":"2026-11-10 13:31:31.964815+00","patch":{"learning":{"task":"Zrób rejestr dla sześciu fikcyjnych paczek. Dodaj powtórzone imię, rozmazany kod i jedną paczkę bez odbiorcy. Przećwicz przekazanie rozbieżności pomocnikowi.","intro":"Przygotujesz prosty rejestr paczek, dzięki któremu znajdziesz właściwy prezent i obsłużysz nieczytelną etykietę.","correct":1,"example":"Gdy kod jest rozmazany, pomocnik odkłada paczkę do sprawdzenia, a animator wręcza kolejną paczkę z potwierdzonym przypisaniem.","options":["Wydam paczki według kolejności, w której dzieci o tym imieniu podeszły do stolika.","Odłożę ją do sprawdzenia, a pomocnik potwierdzi przypisanie przed wydaniem.","Pokażę paczkę obu dzieciom i zapytam publicznie, które spodziewa się opakowania w tym kolorze.","Poproszę, by dzieci podały nazwiska. Jeśli rozpoznam nazwisko, wydam paczkę z rozmazanym kodem."],"feedback":["Kolejność podejścia nie potwierdza tożsamości odbiorcy.","Rozbieżność trzeba wyjaśnić przed wydaniem. Oddzielna kolejka paczek do sprawdzenia pozwala utrzymać porządek bez obciążania dziecka.","Kolor nie pozwala potwierdzić przypisania. Można sprawdzić je spokojnie poza kolejką.","Dodatkowe dane nadal nie potwierdzą, komu przydzielono paczkę z nieczytelnym kodem."],"question":"Co zrobisz z paczką z nieczytelnym oznaczeniem?","situation":"Na spotkaniu są dwoje dzieci o tym samym imieniu. Na jednej paczce widać imię i grupę, a na drugiej rozmazane oznaczenie grupy.","topic_kind":"case_from_existing_curriculum","explanation":"Rozbieżność trzeba wyjaśnić przed wydaniem. Oddzielna kolejka paczek do sprawdzenia pozwala utrzymać porządek bez obciążania dziecka.","quiz_version":4,"quality_review":"requires_subject_expert_review"},"sections":[{"heading":"Paczka i oznaczenie","text":"W większej grupie samo imię nie wystarcza. Umów prosty kod z organizatorem, np. „A04” oznacza pozycję 4 na liście grupy A. Pomocnik ma listę i układa paczki według uzgodnionej kolejności. Do odczytania na sali wystarczy ustalone imię. Lista z przypisaniem pozostaje przy wyznaczonej osobie."},{"heading":"Co zrobić z rozbieżnością","text":"Jeżeli paczka jest nieczytelna lub nie pasuje do listy, odłóż ją w wydzielone miejsce i kontynuuj wręczanie potwierdzonych paczek. Pomocnik weryfikuje kod z osobą, która przygotowała prezenty. Przy znanej rozbieżności organizator rozmawia z opiekunem dyskretnie. Dziecku można podać prostą informację: „Sprawdzamy jedną paczkę i zaraz do ciebie wrócimy”."},{"heading":"Przykład z dwóch takich samych imion","text":"Na liście są „A04, Maja” i „B03, Maja”. Pomocnik zauważa, że obie paczki oznaczono A04. Zostawia je do wyjaśnienia, odczytuje kolejną potwierdzoną pozycję i później wraca do obu Mai. Na sali nie trzeba podawać nazwiska, opisu rodziny ani zawartości paczki."},{"heading":"Sprawdź wynik po wykonaniu","text":"Po próbnej rundzie przy każdym kodzie widnieje wydanie albo jednoznaczna informacja, kto sprawdza rozbieżność. Błędne i nieczytelne paczki pozostają na boku. Żadnego z identycznych imion nie rozstrzygnięto na podstawie wyglądu paczki."}],"practice":{"title":"Co zrobić, gdy paczka nie pasuje do listy","visual":{"title":"Co zrobić, gdy paczka nie pasuje do listy","kind":"flow","entries":[{"label":"Sprawdź kod","detail":"Zestaw etykietę z listą przed wywołaniem imienia."},{"label":"Odłóż rozbieżność","detail":"Wyznacz miejsce na paczki oczekujące na sprawdzenie."},{"label":"Potwierdź z osobą przygotowującą","detail":"Wydaj paczkę dopiero po ustaleniu przypisania."},{"label":"Zapisz wydanie","detail":"Pomocnik odnotowuje rezultat i wraca do oczekującego dziecka."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":4,"updated_at":"2026-11-10 13:31:31.964815+00","patch":{"learning":{"task":"Napisz dwa zdania dla wizyty w bloku i dwa dla spotkania szkolnego. Przećwicz reakcję na śmiech, kolejne pytanie i brak zainteresowania.","intro":"Poprowadzisz świąteczną opowieść tak, aby dziecko mogło się bawić i zadawać pytania na własnych zasadach.","correct":0,"example":"„W naszej opowieści Mikołaja zaprasza gospodarz”. To zdanie działa także w budynku bez komina i zostawia miejsce na różne zwyczaje.","options":["Powiem, że w naszej opowieści gospodarz zaprasza Mikołaja przez drzwi, a każde dziecko może bawić się po swojemu.","Poproszę wszystkie dzieci, by najpierw opowiedziały, w co wierzy ich rodzina, i dopiero wtedy dobiorę historię.","Powiem, że wszystkie dzieci powinny udawać, że widzą komin, żeby młodsi się dobrze bawili.","Udzielę jednej długiej odpowiedzi, która ma rozstrzygnąć za grupę, jak wygląda tradycja Mikołaja."],"feedback":["Sformułowanie „w naszej opowieści” zaprasza do zabawy, pozostawiając dzieciom swobodę interpretacji i reakcję dostosowaną do ich rodzinnej tradycji.","Publiczne wyjaśnianie zwyczajów rodziny może naruszyć prywatność i wykluczyć część dzieci.","Wspólna zabawa może działać przy różnych reakcjach. Dzieci nie muszą potwierdzać opowieści.","Taki wykład narzuca jedną wersję różnym rodzinom. Krótkie zdanie o konwencji tej wizyty wystarczy."],"question":"Która odpowiedź pozwoli podtrzymać zabawę bez presji na grupę?","situation":"Dziecko pyta ze śmiechem: „Jak tu wszedłeś, przecież na dachu nie ma komina?”. Wokół siedzą dzieci z rodzin o różnych zwyczajach.","topic_kind":"case_from_existing_curriculum","explanation":"Sformułowanie „w naszej opowieści” zaprasza do zabawy, pozostawiając dzieciom swobodę interpretacji i reakcję dostosowaną do ich rodzinnej tradycji.","quiz_version":4,"quality_review":"requires_subject_expert_review"},"sections":[{"heading":"Uzgodnij konwencję zabawy","text":"Rodziny obchodzą święta na różne sposoby. Przed wizytą ustal z gospodarzem, jak grupa nazywa postać i czy woli krótką bajkę, rozmowę o tradycji czy samą wizytę kostiumową. Dziecko może wejść w opowieść albo obejrzeć ją z boku. Dorośli mogą wyjaśnić pytania o ich domową tradycję."},{"heading":"Odpowiedz na poziomie pytania","text":"Na pytanie w ramach bajki odpowiedz krótką opowieścią, która pasuje do miejsca. Przy pytaniu o to, co jest prawdziwe, pozwól dziecku nazwać własną obserwację i daj przestrzeń na rozmowę z opiekunem. Opowieść może budować nastrój poprzez rekwizyt, melodię lub jedną wspólną zagadkę. Odkrycie elementu stroju nie wymaga od dziecka składania obietnicy milczenia."},{"heading":"Przykład z bloku bez komina","text":"Dziecko wskazuje domofon i pyta, skąd Mikołaj zna numer mieszkania. Animator mówi: „W naszej świątecznej historii gospodarz spotyka Mikołaja przy drzwiach. Pokażesz, gdzie mam zapukać, jeśli masz ochotę?”. Drugie dziecko wzrusza ramionami. Animator opowiada dalej tylko zainteresowanym."},{"heading":"Sprawdź wynik po wykonaniu","text":"Masz krótką wersję opowieści i neutralne zdanie dla dziecka, które nie chce w nią wejść. W obu wariantach dziecko może zadawać pytania. Twoja odpowiedź pasuje do tego, co uzgodniono z gospodarzem."}],"practice":{"title":"Jak odpowiedzieć na pytanie o tradycję","visual":{"title":"Jak odpowiedzieć na pytanie o tradycję","kind":"comparison","entries":[{"label":"Pytanie w bajce","detail":"Zaproponuj jeden szczegół z opowieści."},{"label":"Pytanie o rzeczywistość","detail":"Uznaj obserwację i zostaw miejsce na rozmowę z opiekunem."},{"label":"Brak zainteresowania","detail":"Pozwól posłuchać z boku lub zająć się czymś innym."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":5,"updated_at":"2026-11-11 08:50:31.084323+00","patch":{"learning":{"task":"Zaznacz na planie miejsca wejście, wyjście, stolik, miejsce oczekiwania i stanowiska dorosłych. Zrób próbę z jednym celowo zastawionym przejściem.","intro":"Ułożysz trasę wizyty i prosty podział zadań, który działa także wtedy, gdy grupa przemieszcza się lub ktoś chce wyjść.","correct":1,"example":"Gdy kolejka wchodzi na drogę wyjścia, animator robi przerwę, a pomocnik i opiekun ustawiają paczki oraz grupę na nowo.","options":["Poproszę oczekujących, by ustawili się ciaśniej pod ścianą, i będę dalej rozdawać paczki.","Wstrzymam zapraszanie. Poproszę opiekuna o zatrzymanie kolejki, a pomocnika o zwolnienie przejścia przed wznowieniem wizyty.","Przeniosę rozdawanie bliżej drzwi, aby skrócić drogę dzieci do paczek.","Poproszę pomocnika o przesunięcie paczek po obsłużeniu kolejnej rodziny."],"feedback":["Kontynuowanie rozdawania podtrzymuje napływ ludzi. Najpierw trzeba udrożnić przejście.","Zatrzymanie zapraszania zapobiega zagęszczaniu grupy. Rozdzielenie zadań pozwala przywrócić wolne przejście bez zostawiania dzieci bez opieki.","Stanowisko przy drzwiach może jeszcze bardziej ograniczyć dostęp do wyjścia.","Przywrócenie wolnego wyjścia ma pierwszeństwo przed kolejną częścią wizyty."],"question":"Co zrobisz w pierwszej kolejności?","situation":"Na spotkaniu w małym holu paczki i kolejka zaczynają blokować wyjście. Kolejna rodzina właśnie wchodzi.","topic_kind":"case_from_existing_curriculum","explanation":"Zatrzymanie zapraszania zapobiega zagęszczaniu grupy. Rozdzielenie zadań pozwala przywrócić wolne przejście bez zostawiania dzieci bez opieki.","quiz_version":4,"quality_review":"requires_subject_expert_review"},"sections":[{"heading":"Zobacz miejsce przed rozpoczęciem","text":"Obejrzyj drogę od drzwi do miejsca spotkania i wyjście z sali. Sprawdź, czy paczki, przewody, wózek i krzesła zostawiają przejście. Umów osobę, która doprowadzi animatora i pomoże zmienić ustawienie, gdy sytuacja się zmieni. W miejscu prywatnym wybierz uzgodnioną przestrzeń wspólną, z opiekunem obecnym przy dziecku."},{"heading":"Zaplanuj ruch ludzi","text":"Stolik i worek ustaw przy boku sali. Zaproś dzieci pojedynczo lub w małych grupach według planu opiekuna. Dziecko może zostać obok bliskiej osoby. Gdy przejście zaczyna się zatykać, zatrzymaj zapraszanie kolejnych osób. Wznów zabawę po przywróceniu swobodnego przejścia i ustaleniu, gdzie stoi pomocnik."},{"heading":"Przykład z małego holu","text":"Wózek przy drzwiach i torba animatora tworzą wąskie gardło. Animator prosi gospodarza o odłożenie wózka w uzgodnionym miejscu, pomocnik przenosi torbę do stolika, a opiekun zatrzymuje na chwilę dzieci. Potem cała grupa przechodzi spokojnie do wolnej części sali."},{"heading":"Pracownia. Zmiany na planie sali","text":"Na kartce narysuj wejście, wyjście, miejsce dla dzieci, paczki i miejsce dla opiekuna. Przejdź schemat na podłodze z dwiema osobami. W jednej rundzie zasłoń umówione miejsce na paczki, w drugiej zaplanuj wyjście dziecka z opiekunem, w trzeciej dodaj kolejkę. Po każdej rundzie zapisz kto zatrzymał zabawę, kto usunął przeszkodę i kiedy można było wznowić wizytę. Przećwicz poprawione ustawienie."},{"heading":"Sprawdź wynik po wykonaniu","text":"Wyjście jest dostępne w każdej rundzie. Paczki mają miejsce poza drogą ruchu. Opiekun i pomocnik wiedzą, kto ma przerwać zapraszanie i komu zgłosić przeszkodę."}],"practice":{"title":"Wizyta i wyjścia","minutes":65,"visual":{"title":"Jak utrzymać wolne przejście","kind":"flow","entries":[{"label":"Przed wejściem","detail":"Umów gospodarza i sprawdź trasę."},{"label":"Ustaw miejsce","detail":"Paczki i kolejka stoją z boku przejścia."},{"label":"Wstrzymaj ruch","detail":"Jeśli przejście się zatyka, opiekun zatrzymuje grupę."},{"label":"Sprawdź i wznów","detail":"Pomocnik usuwa przeszkodę, zanim zaprosisz kolejnych uczestników."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":6,"updated_at":"2026-11-10 13:31:31.964815+00","patch":{"learning":{"task":"Rozpisz próbę pomocy na jednej kartce: pytanie otwierające, granice, termin, potwierdzenie i sposób przyjęcia odmowy.","intro":"Zaplanujesz drobny dobry uczynek, który wynika z rzeczywistej potrzeby drugiej osoby i ma określony zakres.","correct":0,"example":"„W sobotę jadę do punktu odbioru. Czy chcesz, żebym pomógł przy twojej paczce?” daje jasny zakres i możliwość odmowy.","options":["Zapytam sąsiadkę w spokojnej rozmowie, czy potrzebuje wsparcia i jaka forma byłaby dla niej odpowiednia.","Zacznę małą zbiórkę ubrań, a sąsiadka wybierze później, co chce zatrzymać.","Zapytam na grupie osiedlowej, czego sąsiadka może potrzebować.","Najpierw poproszę uczestników o podanie terminów, a potem wybiorę wsparcie pasujące do grafiku."],"feedback":["Rozmowa z odbiorczynią pozwala wybrać potrzebne wsparcie i ustalić sposób, w jaki można je przekazać z poszanowaniem jej decyzji.","Nawet mała zbiórka zakłada potrzebę i przerzuca decyzję o niechcianych rzeczach na odbiorczynię.","Osoby postronne nie określą za sąsiadkę, czy i jakiej pomocy chce. Sprawę warto omówić bezpośrednio.","Dostępność pomaga ustalić zakres po rozpoznaniu potrzeby odbiorczyni."],"question":"Jaki pierwszy krok pozwoli przygotować trafną pomoc?","situation":"Chcesz zorganizować po świętach pomoc dla sąsiadki. Jeden uczestnik proponuje zbiórkę ubrań, ale nikt jeszcze z nią nie rozmawiał.","topic_kind":"case_from_existing_curriculum","explanation":"Rozmowa z odbiorczynią pozwala wybrać potrzebne wsparcie i ustalić sposób, w jaki można je przekazać z poszanowaniem jej decyzji.","quiz_version":4,"quality_review":"requires_subject_expert_review"},"sections":[{"heading":"Zacznij od zapytania","text":"Pomoc jest trafniejsza, gdy odbiorca może określić, czego potrzebuje i w jakiej formie przyjmie wsparcie. Zapytaj: „Czy mogę pomóc w czymś konkretnym w tym tygodniu?”. Jeśli działasz z organizacją, ustal z nią listę potrzeb, sposób przekazania i osobę kontaktową. Przyjmij też odpowiedź, że dana osoba niczego teraz nie potrzebuje."},{"heading":"Ustal zakres i zakończenie","text":"Określ czas, osoby i zasoby potrzebne do zadania. Przy udziale dzieci rolę i miejsce ustal z opiekunami. Zbiórkę prowadź według zasad uzgodnionych z organizatorem, a informacje o odbiorcach przekazuj tylko osobom, które ich potrzebują. Podsumuj, co zostało zrobione, i daj odbiorcy możliwość powiedzenia, czy to pomogło."},{"heading":"Przykład z klatki schodowej","text":"Sąsiadka mówi, że trudno jej odebrać jedną paczkę z punktu odbioru. Umawiacie sobotę i sposób przekazania, który jej pasuje. Po wykonaniu pytasz, czy paczka dotarła. Zachowujesz szczegóły jej sytuacji dla siebie."},{"heading":"Sprawdź wynik po wykonaniu","text":"W planie można wskazać potrzebę uzgodnioną z odbiorcą, konkretny zakres, osobę odpowiedzialną i sposób potwierdzenia wykonania. Plan zawiera także odpowiedź na odmowę lub zmianę zdania."}],"practice":{"title":"Od propozycji do wykonania","visual":{"title":"Od propozycji do wykonania","kind":"flow","entries":[{"label":"Zapytaj","detail":"Ustal potrzebę z osobą lub organizacją."},{"label":"Uzgodnij zakres","detail":"Powiedz, co możesz zrobić i w jakim terminie."},{"label":"Wykonaj i sprawdź","detail":"Potwierdź odbiór lub zakończenie w uzgodniony sposób."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":7,"updated_at":"2026-11-11 08:50:31.084323+00","patch":{"learning":{"task":"Zapisz pięć obserwowalnych zasad, przypisz role i zrób dwie próby z pomiarem. Zaznacz, gdzie użyto rezerwy czasu.","intro":"Zamienisz zasady życzliwości w krótką próbę wizyty z podziałem ról i sprawdzalnym harmonogramem.","correct":0,"example":"Przy opóźnieniu można odpuścić dodatkową piosenkę, zachowując alternatywę odbioru paczki i czas na spokojne przejście.","options":["Każde dziecko może zostać z opiekunem. Pomocnik przygotuje odbiór paczki bez zmiany kolejności, a w razie potrzeby skrócimy dodatkową zabawę.","Zapiszę, że każde dziecko podchodzi na kilka sekund, a zdjęcia zrobimy tylko chętnym.","Zostawię paczki dzieci, które nie podchodzą, na wydanie po wyjściu całej grupy.","Zrezygnuję z zapasu czasu, aby dłuższe podejście dzieci zmieścić w planie."],"feedback":["Kodeks wyraża się w ustawieniu i rolach. Pomocnik może zachować kolejność, a rezygnacja z dodatku chroni dobrowolny udział i tempo.","Dobrowolność dotyczy także podejścia, nie tylko zdjęcia.","Można wręczyć paczkę przez opiekuna w tej samej rundzie bez zmiany zasad dla dzieci.","Zapas pomaga zachować spokój. Udział z miejsca rozwiązuje problem bez dodatkowej presji."],"question":"Który zapis w scenariuszu jest zgodny z kodeksem i pozwala utrzymać tempo?","situation":"W próbie z dwunastoma dziećmi masz 13 minut. Opiekun uprzedza, że dwoje dzieci woli nie podchodzić do fotela.","topic_kind":"case_from_existing_curriculum","explanation":"Kodeks wyraża się w ustawieniu i rolach. Pomocnik może zachować kolejność, a rezygnacja z dodatku chroni dobrowolny udział i tempo.","quiz_version":4,"quality_review":"requires_subject_expert_review"},"sections":[{"heading":"Przysięga jako zasady działania","text":"Zapisz zasady tak, by druga osoba mogła sprawdzić ich wykonanie. „Szanuję wybór” oznacza, że uczestnik może zrezygnować z odpowiedzi, dotyku lub zdjęcia i nadal odebrać prezent. „Dbam o grupę” oznacza, że znasz osoby odpowiedzialne za opiekę, paczki i wolne przejście. Ta lekcja zamyka część przygotowawczą. Dalej przećwiczysz m.in. dostępność, zdjęcia i reagowanie na zmiany."},{"heading":"Policz czas i zostaw zapas","text":"Jeżeli udział jednej osoby trwa przeciętnie 40 sekund, 12 osób potrzebuje 8 minut. Dolicz 2 minuty na powitanie i 3 minuty zapasu, co daje 13 minut. To wynik planowania, który możesz sprawdzić na próbie. Zapisz elementy, które skrócisz przy opóźnieniu, np. drugą piosenkę lub dodatkową kolejkę zdjęć. Zachowaj spokojne tempo i wybór dziecka."},{"heading":"Przykład. Próba z kolejką","text":"Animator prowadzi powitanie, pomocnik sprawdza kody, opiekun dba o dzieci i przejście. W czwartej kolejności paczka okazuje się nieczytelna. Pomocnik odkłada ją do sprawdzenia, animator prosi kolejne dziecko, a osoba mierząca czas zapisuje, ile trwała przerwa. Potem porównajcie to z zapasem w planie."},{"heading":"Pracownia. Dwie pełne próby","text":"Rozpisz scenariusz na wejście, powitanie, wręczanie i zakończenie. Rozdaj kartki ról uczestnikom próby, a obserwatorowi daj listę sygnałów: odmowa zdjęcia, opóźnienie, nieczytelna paczka. Przeprowadź pierwszą próbę z pomiarem czasu. Omów, co obciążyło dziecko lub zakłóciło przejście. Zmień dwa elementy i powtórz próbę w innym składzie ról."},{"heading":"Sprawdź wynik po wykonaniu","text":"Każda osoba umie powiedzieć, co robi przy opóźnieniu. Plan ma realny zapas, a zapis próby pokazuje, co go zużyło. Odmowa nie zatrzymuje dostępu do prezentu, a pomyłkę wyjaśnia pomocnik."}],"practice":{"title":"Próba generalna","minutes":75,"visual":{"title":"Budżet czasu dla dwunastu uczestników","kind":"flow","entries":[{"label":"Powitanie","detail":"2 minuty na zasady i możliwość obserwowania."},{"label":"Wręczanie","detail":"12 × 40 sekund = 8 minut."},{"label":"Zapas","detail":"3 minuty na rozbieżności i spokojne zakończenie."},{"label":"Suma","detail":"13 minut. Zweryfikuj czas podczas próby."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":8,"updated_at":"2026-11-11 06:20:18.367654+00","patch":{"learning":{"task":"Odegraj trzy pierwsze wejścia z partnerem. Po każdym niech wskaże moment, w którym Twój ruch lub głos pomógł mu się zorientować.","intro":"Nauczysz się rozpoznawać pierwsze oznaki wycofania oraz spokojnie zmieniać głośność, tempo i odległość.","correct":0,"example":"Gdy część grupy się cieszy, a jedno dziecko się wycofuje, spokojne powitanie całej grupy daje mu możliwość obserwowania.","options":["Zatrzymam się w widocznym miejscu, powitam grupę spokojnym głosem i zostawię dziewczynce możliwość obserwowania obok taty.","Poproszę tatę, żeby przybliżył dziewczynkę do wejścia, gdy reszta grupy zacznie machać.","Zwrócę się wyłącznie do dziewczynki cichym głosem, aż odwróci głowę w moją stronę.","Od razu zacznę głośne powitanie grupowe, a po pierwszej rundzie sprawdzę, jak zareagowała."],"feedback":["Pierwszy krok to dostosowanie własnej odległości i głośności. Dziewczynka ma bezpieczne miejsce obok taty, a grupa może rozpocząć spotkanie.","Przemieszczenie skraca dystans dziecka, zanim samo zdecyduje, czy jest na to gotowe.","Cichy głos pomaga, ale skupienie całej uwagi na niej może pogłębić dyskomfort.","Zauważony sygnał pozwala ściszyć i zwolnić już teraz."],"question":"Jak poprowadzisz pierwsze chwile spotkania?","situation":"Przy wejściu do sali część grupy macha, a dziewczynka za tatą odwraca twarz i mocno trzyma jego dłoń.","topic_kind":"authored_holiday_scenario","explanation":"Pierwszy krok to dostosowanie własnej odległości i głośności. Dziewczynka ma bezpieczne miejsce obok taty, a grupa może rozpocząć spotkanie.","quiz_version":4,"quality_review":"editorial_pending"},"sections":[{"heading":"Daj grupie czas na orientację","text":"Zatrzymaj się w widocznym miejscu i przywitaj całą grupę normalnym głosem. Nie wchodź od razu między dzieci. Pokaż, gdzie można zostać z opiekunem i co się wydarzy przez najbliższą chwilę. Głośny dzwonek i nagłe podejście mogą zaskoczyć, nawet gdy dziecko czekało na wizytę."},{"heading":"Reaguj na sygnały bez zgadywania","text":"Cofnięcie się, zasłonięcie twarzy lub chwyt za rękę opiekuna wskazują, że warto zrobić miejsce. Zatrzymaj ruch w stronę dziecka, ścisz głos i pozwól opiekunowi zdecydować, czy chce podejść bliżej. Jeśli dziecko po chwili samo nawiązuje kontakt, odpowiedz z miejsca i poczekaj na jego następny krok."},{"heading":"Przykład z pierwszych trzydziestu sekund","text":"W sali słychać śmiech. Jedno dziecko mocno trzyma rękę taty. Animator zostaje przy wejściu, odkłada dzwonek i mówi do grupy: „Możecie popatrzeć stąd, będę przy choince”. Tata pozostaje obok dziecka, a animator zaczyna spokojną rozmowę z grupą."},{"heading":"Sprawdź wynik po wykonaniu","text":"W próbie obserwator potrafi powiedzieć, w którym momencie zmieniłeś głos, odległość lub tempo. Po sygnale wycofania nie skróciłeś dystansu, a grupa wiedziała, że może oglądać z miejsca."}],"practice":{"title":"Pierwsze powitanie: zbuduj poczucie bezpieczeństwa","minutes":35,"visual":{"title":"Zauważ sygnał i dostosuj powitanie","kind":"comparison","entries":[{"label":"Dziecko samo podchodzi","detail":"Przywitaj spokojnie i zostaw mu wybór odległości."},{"label":"Dziecko obserwuje z opiekunem","detail":"Mów do całej grupy, zostaw dziecku czas."},{"label":"Dziecko cofa się lub zasłania twarz","detail":"Zatrzymaj podejście, ścisz głos i zachowaj przestrzeń."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":9,"updated_at":"2026-11-11 06:20:18.367654+00","patch":{"learning":{"task":"Przećwicz wydanie trzech różnych paczek. Dodaj pytanie o rozmiar, podejrzenie zamiany i komentarz o cenie. Odpowiedz na każde w jednym lub dwóch zdaniach.","intro":"Przećwicz wręczanie różnych prezentów bez tworzenia publicznego rankingu dzieci, rodzin ani zawartości paczek.","correct":2,"example":"„Widzę, że różnica zwróciła twoją uwagę. Możemy spokojnie porozmawiać o tym z opiekunem” uznaje emocje i nie wystawia publicznej oceny.","options":["Wyjaśnię dzieciom, jak organizator podzielił budżet, aby pokazać, że paczki są sprawiedliwe.","Poproszę grupę, by porównała, ile rzeczy każdy znalazł, i pokazała dziecku, że też dostało dużo.","Uznaję, że różnica może je zmartwić. Powiem, że paczki mogą się różnić i że możemy spokojnie porozmawiać z opiekunem.","Obiecam dziecku większą paczkę po zakończeniu, żeby przestało się martwić."],"feedback":["Ujawnienie wartości podtrzymuje ranking prezentów i pomija uczucie dziecka.","Publiczne liczenie przenosi uwagę na kolejne porównanie.","Dziecko łączy różnicę w opakowaniu lub zawartości z własną wartością. Najpierw warto uznać uczucie, zapewnić życzliwy kontakt i zaproponować rozmowę z opiekunem.","Obietnica bez uzgodnienia może wywołać dalsze rozczarowanie. Możesz od razu okazać uwagę i wysłuchać."],"question":"Jak odpowiesz dziecku przy grupie?","situation":"Po otwarciu paczek jedno dziecko mówi, że jego prezent jest mały i zastanawia się, czy przez to było mniej ważne. Opiekun stoi obok.","topic_kind":"authored_holiday_scenario","explanation":"Dziecko łączy różnicę w opakowaniu lub zawartości z własną wartością. Najpierw warto uznać uczucie, zapewnić życzliwy kontakt i zaproponować rozmowę z opiekunem.","quiz_version":4,"quality_review":"editorial_pending"},"sections":[{"heading":"Oddziel prezent od oceny osoby","text":"Różne rozmiary paczek mogą mieć praktyczne przyczyny: opakowanie, rodzaj przedmiotu lub ustalenia rodziny. Komentarze o cenie, wielkości i zasługach łatwo zamieniają wręczanie w porównanie. Ustal z organizatorem jedno proste powitanie i sposób wydania niezależny od wyglądu paczki."},{"heading":"Zareaguj na pytanie o różnicę","text":"Uznaj obserwację dziecka i powiedz, co możesz potwierdzić. Jeżeli zawartość ma być prywatna, możesz zaproponować otwarcie z opiekunem. Jeśli prawdopodobnie doszło do zamiany, sprawdź przypisanie dyskretnie i dopiero wtedy wróć z wynikiem. Sprawę oczekiwań i budżetu zostaw organizatorowi i rodzinie."},{"heading":"Przykład ze świetlicy","text":"Olek zauważa, że jego paczka jest w kopercie, a obok stoi duże pudło. Animator mówi: „Widzę, że paczki mają różne opakowania. Sprawdźmy twoje imię z listą. Otworzysz z opiekunem, jeśli chcesz”. Po odczytaniu kodu pomocnik potwierdza poprawne przypisanie."},{"heading":"Sprawdź wynik po wykonaniu","text":"W próbnej rundzie przy każdej paczce używasz tak samo życzliwego komunikatu. Rozbieżność trafia do sprawdzenia, a pytanie dziecka o wielkość otrzymuje spokojną odpowiedź bez podawania ceny ani oceny osoby."}],"practice":{"title":"Prezenty bez porównywania dzieci","minutes":35,"visual":{"title":"Trzy sytuacje przy rozdawaniu prezentów","kind":"comparison","entries":[{"label":"Różne opakowania","detail":"Opisz wygląd, jeśli dziecko pyta. Zachowaj prywatność zawartości."},{"label":"Zamienione oznaczenia","detail":"Wstrzymaj wydanie i poproś o weryfikację przypisania."},{"label":"Pytanie o sprawiedliwość","detail":"Uznaj uczucie. Do ustaleń wróć z opiekunem osobno."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":10,"updated_at":"2026-11-11 06:20:18.367654+00","patch":{"learning":{"task":"Przygotuj dwie karty wyboru i odegraj trzy warianty: wskazanie, odłożenie kart i ciszę. Zapisz, jak w każdym wariancie kończysz rozmowę.","intro":"Zaproponujesz kilka dostępnych sposobów komunikacji i przećwiczysz czekanie na reakcję bez wyręczania dziecka.","correct":1,"example":"Pokazujesz karty „pomachaj” i „popatrz”. Dziecko wskazuje drugą, więc spokojnie dajesz mu obserwować.","options":["Poproszę opiekunkę, żeby wybrała jedną kartę za dziecko, dzięki czemu spotkanie pójdzie płynniej.","Zaproponuję dwie dostępne możliwości z użyciem kart, dam czas na wskazanie i pozwolę pozostać obserwatorem.","Poproszę dziecko o odpowiedź słowem albo skinieniem, zanim sięgnę po karty.","Powtórzę pytanie wyraźniej, a milczenie potraktuję jako zgodę na wręczenie paczki z bliska."],"feedback":["Opiekunka może pomóc udostępnić karty. Najpierw warto dać dziecku możliwość dokonania wyboru.","Propozycja odwołuje się do dostępnej metody. Czas na reakcję i możliwość obserwowania pozostawiają dziecku rzeczywistą decyzję.","Karty są już uzgodnionym sposobem komunikacji, więc można użyć ich od początku.","Milczenie nie daje informacji o zgodzie na bliski kontakt. Ustal sposób odbioru z poszanowaniem przestrzeni."],"question":"Jak zaprosisz dziecko do kontaktu?","situation":"Dziecko nie odpowiada słowami na powitanie. Opiekunka mówi, że zwykle komunikuje wybór wskazaniem obrazka i ma karty przy sobie.","topic_kind":"authored_holiday_scenario","explanation":"Propozycja odwołuje się do dostępnej metody. Czas na reakcję i możliwość obserwowania pozostawiają dziecku rzeczywistą decyzję.","quiz_version":4,"quality_review":"editorial_pending"},"sections":[{"heading":"Daj dostępny wybór","text":"Dziecko może przekazać odpowiedź ruchem, wzrokiem, obrazkiem, przyciskiem komunikatora albo słowem. Użyj jednego zaproszenia i daj chwilę na reakcję. Jeśli opiekun zna preferowany sposób komunikacji, zapytaj o niego spokojnie przed spotkaniem. Mów do dziecka, zachowując jego zwykły sposób kontaktu i miejsce obok zaufanej osoby."},{"heading":"Zostaw ciszę i możliwość odmowy","text":"Brak mowy może wynikać z wielu przyczyn i nie pozwala wnioskować o zrozumieniu, zainteresowaniu ani zgodzie. Zaproponuj dwie konkretne możliwości, np. pomachanie lub samo patrzenie. Jeśli dziecko nie wybiera żadnej, zakończ pytanie i zostaw mu możliwość obserwacji. Zostaw jego pomoce komunikacyjne w zasięgu i uzgodnij z opiekunem sposób przekazania paczki."},{"heading":"Przykład z obrazkami","text":"Organizator wcześniej przygotował karty „pomachaj” i „popatrz”. Dziecko wskazuje drugą. Animator mówi: „Dobrze, możesz popatrzeć”. Karty służą komunikacji, więc mogą też pomóc zakomunikować przerwę. Przy kolejnym spotkaniu opiekun potwierdza, czy dziecko nadal chce używać tych kart."},{"heading":"Sprawdź wynik po wykonaniu","text":"Po każdym pytaniu zostawiłeś czas na reakcję. W scenie z gestem zareagowałeś na gest, a w scenie z ciszą zakończyłeś zaproszenie bez nacisku. Dziecko nadal mogło dostać paczkę i pozostać przy opiekunie."}],"practice":{"title":"Spotkanie z dzieckiem, które nie mówi","minutes":35,"visual":{"title":"Wybór dostępnego sposobu komunikacji","kind":"flow","entries":[{"label":"Zapytaj raz","detail":"Użyj krótkiego zdania i mów bezpośrednio do dziecka."},{"label":"Daj opcje","detail":"Skorzystaj z uzgodnionego gestu, obrazka lub komunikatora."},{"label":"Poczekaj","detail":"Zostaw czas na odpowiedź w wybranej formie."},{"label":"Zakończ spokojnie","detail":"Cisza pozwala przejść dalej z opcją obserwowania."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":11,"updated_at":"2026-11-11 06:20:18.367654+00","patch":{"learning":{"task":"Wypełnij plan dla zdjęcia rodzinnego, grupowego i do otwartego posta. Przy każdym zapisz odbiorcę, osobę decyzyjną i wariant udziału poza kadrem.","intro":"Ułożysz z organizatorem zasady fotografowania i osobno sprawdzisz, co wolno zrobić z gotowym zdjęciem.","correct":3,"example":"Organizator może zastąpić prywatny portret zdjęciem pustej scenografii, po sprawdzeniu, czy nie ma osób w tle.","options":["Przekażę zdjęcie do publicznego posta bez podpisu, bo nikt nie zobaczy nazwiska dziecka.","Przekażę zdjęcie do krótkiej relacji, a fotografię do posta zatrzymam dla rodziny.","Opublikuję zdjęcie po wysłaniu rodzicowi informacji, że może poprosić o jego usunięcie.","Zachowam uzgodniony prywatny obieg i poproszę organizatora o wybór materiału, który wolno opublikować."],"feedback":["Rozpoznawalność zdjęcia nie zależy wyłącznie od podpisu. Zakres pozostaje prywatny.","Relacja na publicznym profilu również oznacza udostępnienie poza uzgodnionym obiegiem.","Informacja po decyzji o publikacji nie zastępuje wcześniej ustalonej podstawy i zakresu.","Zdjęcie rodzinne przekazano do określonego celu. Organizator potrzebuje osobnego ustalenia, zanim użyje rozpoznawalnego zdjęcia w publicznym kanale."],"question":"Co zrobisz z fotografią przeznaczoną dla rodziny?","situation":"Rodzic zgodził się na fotografię dla rodziny. Po wizycie osoba prowadząca publiczny profil wydarzenia prosi o zdjęcie portretowe dziecka.","topic_kind":"authored_holiday_scenario","explanation":"Zdjęcie rodzinne przekazano do określonego celu. Organizator potrzebuje osobnego ustalenia, zanim użyje rozpoznawalnego zdjęcia w publicznym kanale.","quiz_version":4,"quality_review":"editorial_pending"},"sections":[{"heading":"Zapisz osobno wykonanie i publikację","text":"Przed wydarzeniem ustal z organizatorem, kto fotografuje, dla kogo są zdjęcia i gdzie mają trafić. Zdjęcie na prywatną pamiątkę, przesłanie uczestnikom i publikacja w otwartym profilu mają różny zakres. Przy zaplanowanej publikacji rozpoznawalnego wizerunku dziecka organizator ustala odpowiednią podstawę i zasady. Gdy opiera się na zgodzie, powinna określać cel i miejsca publikacji oraz sposób wycofania."},{"heading":"Sprawdź, jak dziecko chce uczestniczyć","text":"Uprzedź przed zdjęciem i daj dziecku możliwość odwrócenia się lub odejścia. Dziecko, które odmawia, nadal może wziąć udział w zabawie i odebrać prezent. Ustal z fotografem, gdzie można stać poza kadrem. Przy zdjęciu grupowym sprawdź także osoby w tle. Gdy zasady są niejasne, przekaż sprawę osobie odpowiedzialnej przed zrobieniem lub wysłaniem zdjęcia."},{"heading":"Przykład z prywatną pamiątką","text":"Rodzic i dziecko chcą zdjęcie do rodzinnego albumu. Organizator proponuje później otwarty post z tego samego zdjęcia. Animator przekazuje ustalenie fotografowi i organizatorowi. Rodzinne ujęcie pozostaje w ustalonym obiegu, a do posta wybierają fotografię scenografii bez osób w tle."},{"heading":"Sprawdź wynik po wykonaniu","text":"Dla każdego ujęcia potrafisz wskazać zakres, odpowiedzialną osobę i miejsce poza kadrem. Zgoda na zdjęcie rodzinne nie została użyta do posta. Dziecko, które odmawiało, pozostało uczestnikiem zabawy."}],"practice":{"title":"Zdjęcia i zgoda na publikację","minutes":35,"visual":{"title":"Decyzje przed zrobieniem i przed udostępnieniem zdjęcia","kind":"comparison","entries":[{"label":"Pamiątka dla rodziny","detail":"Ustal, kto robi zdjęcie i kto je otrzyma."},{"label":"Publikacja organizatora","detail":"Zweryfikuj zakres i podstawę przed przekazaniem materiału do posta."},{"label":"Odmowa lub niejasność","detail":"Zostaw możliwość udziału poza kadrem i wyjaśnij zasady przed wysłaniem."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":12,"updated_at":"2026-11-11 06:20:18.367654+00","patch":{"learning":{"task":"Rozrysuj role dla grupy 20 dzieci. Odegraj brak pomocnika i prośbę o wyjście. Zapisz zmianę podziału zadań zatwierdzoną przez placówkę.","intro":"Ustalisz z placówką role dorosłych i zaplanujesz przebieg krótkiego spotkania dla całej grupy.","correct":1,"example":"Drugi pracownik może towarzyszyć dziecku podczas przerwy, a wychowawca pozostaje z grupą i uzgadnia dalszy program z animatorem.","options":["Poproszę oboje pracowników, żeby wyszli z dzieckiem. Sam poprowadzę pozostałą grupę do ich powrotu.","Uzgodnię z wychowawcą, który pracownik zajmie się dzieckiem, i dostosuję przebieg do osoby pozostającej z grupą.","Wyjdę z dzieckiem, a wychowawca przejmie moją część programu dla grupy.","Poproszę dziecko o samodzielne wyjście do szatni i po zakończeniu poinformuję wychowawcę."],"feedback":["Animatorowi powierzono program, a placówka musi utrzymać uzgodniony nadzór w sali.","Rozmowa z wychowawcą uruchamia wcześniej ustalony plan. Grupa ma opiekuna, a dziecko ma wsparcie podczas przerwy.","Wyjście organizuje wyznaczony opiekun, zgodnie z ustaleniami placówki.","Placówka powinna uczestniczyć w ustalaniu przerwy i nadzoru od chwili zgłoszenia."],"question":"Jak zorganizujesz dalsze spotkanie zgodnie z podziałem ról?","situation":"W przedszkolu podczas wręczania paczek jedno dziecko prosi o wyjście. W sali jest dwoje wyznaczonych pracowników placówki i animator.","topic_kind":"authored_holiday_scenario","explanation":"Rozmowa z wychowawcą uruchamia wcześniej ustalony plan. Grupa ma opiekuna, a dziecko ma wsparcie podczas przerwy.","quiz_version":4,"quality_review":"editorial_pending"},"sections":[{"heading":"Podział zadań przed wejściem","text":"Placówka wyznacza dorosłych do nadzoru nad grupą i podaje zasady obowiązujące przy udziale gości. Animator prowadzi uzgodnioną część spotkania. Pomocnik odpowiada za przygotowanie i kolejność paczek. Ustal, kto decyduje o przerwie, kto reaguje na potrzebę wyjścia dziecka i kto kontaktuje się z dyrekcją lub opiekunem."},{"heading":"Zaplanuj udział, również z miejsca","text":"Poinformuj o trzech częściach wizyty: powitanie, aktywność i odbiór paczek. Dzieci mogą obserwować z opiekunem lub przy własnym stoliku. Zapytaj placówkę o spokojną alternatywę i o sposób przekazania potrzeb bez ujawniania danych grupie. Jeśli program obejmuje przekąski, ustal z placówką sposób ich wydania oraz weryfikację składu przed poczęstunkiem."},{"heading":"Przykład z przedszkola","text":"W grupie jest 20 dzieci. Wychowawczyni pozostaje z grupą, drugi pracownik może wyjść z dzieckiem, a pomocnik odczytuje kody paczek. Kiedy jedno dziecko prosi o przerwę, wychowawczyni daje sygnał drugiemu pracownikowi. Animator spokojnie kontynuuje krótką zabawę z resztą grupy."},{"heading":"Sprawdź wynik po wykonaniu","text":"Każda rola ma osobę i zastępstwo. Gdy ktoś wychodzi z dzieckiem, wiadomo, kto zostaje z grupą. Na planie masz też miejsce dla dzieci obserwujących oraz ustalony sposób powrotu do zajęć."}],"practice":{"title":"Świąteczna wizyta w przedszkolu i szkole","minutes":35,"visual":{"title":"Kto odpowiada za którą część wizyty","kind":"comparison","entries":[{"label":"Wyznaczeni opiekunowie","detail":"Nadzór nad dziećmi i organizacja przerwy."},{"label":"Animator","detail":"Powitanie i prowadzenie umówionej aktywności."},{"label":"Pomocnik","detail":"Sprawdzenie, ułożenie i przekazanie paczek."},{"label":"Osoba kontaktowa placówki","detail":"Decyzja przy zmianie planu oraz kontakt z dyrekcją i opiekunami."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":13,"updated_at":"2026-11-11 06:20:18.367654+00","patch":{"learning":{"task":"Odegraj trzy sygnały wycofania. Zapisz znak do wyłączenia dźwięku, spokojną aktywność i zdanie oferujące wybór.","intro":"Zaplanujesz spokojny wariant wizyty i zareagujesz, gdy dźwięk zacznie przeszkadzać uczestnikowi.","correct":0,"example":"Gdy dziecko zasłania uszy, wyłącz muzykę i przejdź do spokojnej zagadki. Opiekun może zaproponować miejsce z boku lub przerwę.","options":["Dam znak do wyłączenia muzyki, zrobię krótką pauzę i umożliwię dziecku spokojniejszy udział albo przerwę z opiekunem.","Zapowiem, że utwór potrwa tylko pół minuty, po czym zaproponuję spokojniejszą zabawę.","Poproszę dziecko, żeby przesunęło się dalej od głośnika, utrzymując dotychczasowy program.","Przerwę muzykę do chwili, aż dziecko zgodzi się wrócić na środek sali."],"feedback":["Zmiana dźwięku jest możliwa od razu. Pauza i wybór formy udziału dają dziecku czas na ustalenie z opiekunem, czego potrzebuje.","Przy zauważonej reakcji można przerwać dźwięk od razu.","Zmiana miejsca może pomóc po ściszeniu. Najpierw warto usunąć przeszkodę, na którą grupa ma wpływ.","Powrót na środek nie jest warunkiem dalszego udziału. Spokojna wersja działa także z obserwatorem z boku."],"question":"Jak zareagujesz w tym momencie?","situation":"Podkład zaczyna grać głośniej, a dziecko zasłania uszy i przestaje uczestniczyć w zabawie. Pomocnik stoi przy głośniku.","topic_kind":"authored_holiday_scenario","explanation":"Zmiana dźwięku jest możliwa od razu. Pauza i wybór formy udziału dają dziecku czas na ustalenie z opiekunem, czego potrzebuje.","quiz_version":4,"quality_review":"editorial_pending"},"sections":[{"heading":"Przewidywalne dźwięki i zmiany","text":"Przed wizytą zapytaj organizatora, które elementy mogą być zbyt intensywne. Zapowiedz moment muzyki albo zrezygnuj z nagłego dzwonka. Ustal miejsce spokojniejszego udziału i przejście do niego z opiekunem. Poinformuj o tej możliwości całą grupę, aby każde dziecko mogło z niej skorzystać bez tłumaczenia przyczyny."},{"heading":"Dostosuj otoczenie po sygnale","text":"Gdy dziecko zasłania uszy, cofa się lub prosi o przerwę, ścisz albo wyłącz dźwięk i zwolnij. Daj dziecku i opiekunowi czas na decyzję o pozostaniu, przerwie lub powrocie. Unikaj testowania, ile dziecko jeszcze zniesie. Jeżeli jedno źródło dźwięku trudno szybko wyłączyć, przerwij program i z pomocą opiekuna zaproponuj spokojniejsze miejsce."},{"heading":"Przykład z sali z muzyką","text":"Pomocnik włącza podkład, a dziecko zasłania uszy. Animator daje umówiony znak do wyłączenia głośnika i robi pauzę. Opiekun pokazuje dziecku miejsce z dala od głośnika. Po chwili grupa wybiera cichą zgadywankę, a dziecko decyduje, czy chce wrócić."},{"heading":"Sprawdź wynik po wykonaniu","text":"Pomocnik rozpoznał znak wyłączenia dźwięku. Uczestnik mógł wybrać miejsce lub przerwę. Alternatywna aktywność była gotowa i nie zależała od tego, czy dziecko wróci."}],"practice":{"title":"Komunikacja z dzieckiem wrażliwym na hałas","minutes":35,"visual":{"title":"Kolejność reakcji na zbyt głośny dźwięk","kind":"flow","entries":[{"label":"Zauważ","detail":"Dziecko zasłania uszy lub sygnalizuje potrzebę przerwy."},{"label":"Ścisz i zatrzymaj","detail":"Wyłącz źródło albo wstrzymaj głośną część programu."},{"label":"Daj wybór","detail":"Spokojniejsze miejsce lub przerwa z opiekunem."},{"label":"Wróć do planu w spokojnej wersji","detail":"Dziecko decyduje o powrocie."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":14,"updated_at":"2026-11-11 06:20:18.367654+00","patch":{"learning":{"task":"Przećwicz krótkie odpowiedzi na prośbę o powrót rodzica, drogi prezent i poprawę zdrowia bliskiego. Podkreśl każdy krok, który naprawdę możesz wykonać.","intro":"Ułożysz odpowiedź, która uznaje emocje dziecka i zawiera wyłącznie obietnicę, nad którą masz kontrolę.","correct":2,"example":"Gdy nie znasz terminu powrotu bliskiej osoby, możesz uznać tęsknotę i zaproponować rozmowę z zaufanym dorosłym.","options":["Powiem, że jeśli bardzo tego pragnie, tata prawdopodobnie zdąży wrócić. Na koniec zaproponuję rozmowę z wychowawczynią.","Poproszę dziecko o opisanie rodzinnych powodów wyjazdu, żebym mógł ocenić szanse na powrót.","Powiem, że słyszę, jak bardzo tęskni, i że nie wiem, kiedy tata wróci. Jeśli zechce, zaprosimy wychowawczynię do rozmowy.","Przekieruję rozmowę od razu do listy prezentów, żeby nie rozpoczynać smutnego tematu."],"feedback":["Zachęta do rozmowy jest dobra. Prognoza pozostaje niepotwierdzona i może stać się dla dziecka obietnicą.","Sprawa jest prywatna, a animator nie ma podstaw do prognozowania.","Można uznać tęsknotę i zaproponować dostępne wsparcie bez rozstrzygania sytuacji rodzinnej.","Krótkie uznanie tęsknoty pomaga dziecku zostać wysłuchanym. Potem może samo wybrać dalszą rozmowę."],"question":"Co odpowiesz dziecku?","situation":"Dziecko cicho pyta, czy możesz sprawić, żeby tata wrócił przed świętami. Na miejscu jest zaufana wychowawczyni.","topic_kind":"authored_holiday_scenario","explanation":"Można uznać tęsknotę i zaproponować dostępne wsparcie bez rozstrzygania sytuacji rodzinnej.","quiz_version":4,"quality_review":"editorial_pending"},"sections":[{"heading":"Uznaj uczucie bez oceny sytuacji","text":"Gdy dziecko mówi o tęsknocie, chorobie bliskiej osoby lub drogiej rzeczy, możesz powiedzieć: „Widzę, że to dla ciebie ważne”. Zostaw chwilę na jego reakcję. Przy innych uczestnikach unikaj pytań o szczegóły rodzinne. Ustal z zaufanym opiekunem, czy chce towarzyszyć dziecku w dalszej rozmowie."},{"heading":"Obiecuj wyłącznie konkret, który możesz wykonać","text":"Obietnica zakupu, powrotu rodzica lub poprawy zdrowia wykracza poza rolę animatora. Możesz natomiast zostać na miejscu przez krótką chwilę lub zawołać osobę, której dziecko ufa. Gdy odpowiedź zależy od organizatora, zaproponuj sprawdzenie i uzgodnij, kto wróci z informacją."},{"heading":"Przykład z listem do Mikołaja","text":"Dziecko daje list z prośbą o powrót chorego dziadka. Animator mówi: „Dziękuję, że mi o tym opowiedziałeś. Widać, że bardzo ci zależy. Czy chcesz, żebyśmy poprosili panią Kasię, żeby z nami usiadła?”. O dalszym kontakcie decydują dziecko i opiekunka."},{"heading":"Sprawdź wynik po wykonaniu","text":"Twoja wypowiedź zawiera rozpoznanie potrzeby lub uczucia, uczciwą granicę i propozycję realnego kroku. Gdy obiecujesz konkretną rzecz, potrafisz wykonać ją w ustalonym czasie."}],"practice":{"title":"Życzliwość bez obietnic niemożliwych do spełnienia","minutes":35,"visual":{"title":"Jak ułożyć odpowiedź na trudne życzenie","kind":"flow","entries":[{"label":"Uznaj","detail":"„Słyszę, że bardzo ci na tym zależy”."},{"label":"Nazwij granicę","detail":"„Nie wiem, kiedy tata będzie mógł przyjechać”."},{"label":"Zaproponuj wsparcie","detail":"„Jeśli chcesz, możemy chwilę poczekać tu z opiekunem”."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":15,"updated_at":"2026-11-11 06:20:18.367654+00","patch":{"learning":{"task":"Napisz jedną reakcję na rozpoznanie głosu i jedną na pytanie wprost. Odegraj także wariant, w którym dziecko odmawia pomocy.","intro":"Przećwiczysz reakcję na pytanie o osobę w kostiumie w grupie dzieci z różnymi świątecznymi zwyczajami.","correct":1,"example":"„Dziś bawimy się w świąteczną wizytę. Możesz dołączyć albo patrzeć z miejsca” pozostawia dziecku decyzję.","options":["Wezmę dziecko na bok i poproszę o obietnicę, że nikomu o tym nie opowie.","Uznaję, że głos jest znajomy, i mówię, że dziś organizujemy świąteczną zabawę, w której każdy może uczestniczyć po swojemu.","Zaproszę dziecko do pomocników pod warunkiem, że poprze moją wersję historii przy grupie.","Oddam głos młodszym dzieciom i poproszę je, żeby rozstrzygnęły, kto ma rację."],"feedback":["Obietnica milczenia ogranicza możliwość swobodnej rozmowy o tym, co dziecko widziało.","Wspólna zabawa może pomieścić różne obserwacje. Krótka odpowiedź i otwarta propozycja udziału pozwalają grupie kontynuować spotkanie.","Pomoc powinna być dobrowolna i dostępna bez popierania konkretnej wersji opowieści.","Publiczne głosowanie może zawstydzić dziecko i narzucić grupie rozstrzyganie prywatnych przekonań."],"question":"Jak odpowiesz, by uszanować obserwację i pozwolić grupie dalej się bawić?","situation":"Przy młodszych dzieciach dziesięciolatek mówi: „To nasz sąsiad w kostiumie, poznaję go po głosie”.","topic_kind":"authored_holiday_scenario","explanation":"Wspólna zabawa może pomieścić różne obserwacje. Krótka odpowiedź i otwarta propozycja udziału pozwalają grupie kontynuować spotkanie.","quiz_version":4,"quality_review":"editorial_pending"},"sections":[{"heading":"Uznaj obserwację dziecka","text":"Dziecko może rozpoznać głos, zobaczyć element kostiumu lub wprost zapytać, czy to zabawa. Możesz spokojnie powiedzieć: „Dobrze zauważyłeś, dziś bawimy się w świąteczną wizytę”. Starsze dziecko może pomóc w zabawie, jeżeli samo ma na to ochotę. Równie dobrą możliwością jest dalsze obserwowanie."},{"heading":"Zachowaj miejsce na różne zwyczaje","text":"Kiedy kilka dzieci pyta o swoje rodzinne tradycje, odpowiedz o obecnej zabawie i pozwól im później wrócić do tematu z opiekunem. Wspólną uwagę przekieruj do aktywności, w której każdy może wziąć udział. Dziecko może opowiedzieć opiekunowi o wszystkim, co zauważyło na wydarzeniu."},{"heading":"Przykład z rozpoznanym głosem","text":"Starsza siostra mówi: „Poznałam głos sąsiada!”. Animator odpowiada: „Masz uważne ucho. Dzisiaj robimy świąteczną zabawę. Jeśli chcesz, możesz pomóc układać zagadki”. Jeśli siostra odmawia, dołącza do grupy na dotychczasowych zasadach."},{"heading":"Sprawdź wynik po wykonaniu","text":"W próbie dziecko mogło nazwać obserwację, odmówić pomocy i porozmawiać z opiekunem. Zachowałeś przyjazny ton, a grupa miała wspólną aktywność bez przymusu przyjęcia jednej wersji opowieści."}],"practice":{"title":"Gdy dziecko zna prawdę o Mikołaju","minutes":35,"visual":{"title":"Trzy decyzje po rozpoznaniu kostiumu","kind":"flow","entries":[{"label":"Uznaj obserwację","detail":"Odpowiedz spokojnie na to, co dziecko zauważyło."},{"label":"Nazwij zabawę","detail":"Skup się na konwencji bieżącego spotkania."},{"label":"Daj wybór","detail":"Pomoc przy zabawie, obserwacja lub rozmowa z opiekunem."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":16,"updated_at":"2026-11-11 06:20:18.367654+00","patch":{"learning":{"task":"Ułóż dwa warianty zajęć dla dwunastu dzieci. Policz materiały i czas przygotowania, sprawdź, ile osób jednocześnie skorzysta, i wybierz plan.","intro":"Zaplanujesz świąteczną aktywność przy ograniczonym budżecie i ocenisz, co nadaje się do ponownego użycia.","correct":3,"example":"Karton można wykorzystać jako podkładkę do kartek. Osoba, która woli obserwować, może uczestniczyć w przygotowanej opowieści.","options":["Poproszę każdą rodzinę o przyniesienie zestawu nowych przyborów, żeby wszystkie kartki wyglądały podobnie.","Rozdzielę tylko osiem najlepiej wyglądających kopert. Dzieci bez kopert będą obserwować.","Zrobię obowiązkowe kartki z całego dostępnego papieru. Jeśli zostanie czas, przeczytam opowieść.","Przygotujemy kartki z dostępnego papieru i stanowiska do wspólnego rysowania. Zaproponujemy też krótką opowieść tym, którzy wolą słuchać."],"feedback":["Koszt przenosi się na rodziny, mimo że grupa ma potrzebne przybory.","Koperta nie musi określać dostępu do wspólnego zadania ani sposobu uczestnictwa.","Liczba zużytych materiałów nie jest celem. Przygotowana wcześniej opowieść daje równorzędny wybór.","Plan korzysta z tego, co grupa ma na miejscu, i pozwala uczestniczyć zarówno przez rysowanie, jak i słuchanie."],"question":"Który plan zapewni dostępny udział całej grupie?","situation":"Na zajęcia dla dwunastu dzieci macie czyste materiały papierowe, wspólne kredki i zerowy budżet na zakupy. Część dzieci woli słuchać niż rysować.","topic_kind":"authored_holiday_scenario","explanation":"Plan korzysta z tego, co grupa ma na miejscu, i pozwala uczestniczyć zarówno przez rysowanie, jak i słuchanie.","quiz_version":4,"quality_review":"editorial_pending"},"sections":[{"heading":"Zrób spis przed zakupami","text":"Sprawdź, jakie przybory, czyste opakowania i rekwizyty są już dostępne. Do zajęć z dziećmi wybierz materiały w dobrym stanie i dopasowane do wieku grupy. Wyklucz ostre krawędzie, zszywki i przedmioty z nieznanym składem. Jeśli jakieś wyposażenie potrzebne jest jednorazowo, sprawdź, czy placówka może je pożyczyć."},{"heading":"Porównaj koszt, czas i rezultat","text":"Aktywność bez nowych zakupów może wymagać przygotowania. Porównaj minuty pracy, liczbę stanowisk, ilość materiałów do sprzątnięcia i to, czy wszyscy mogą skorzystać. Ustal miejsce odkładania przedmiotów do ponownego użycia. Kartka, wspólna opowieść lub zabawa w grupie mogą być upominkiem, jeśli uczestnicy chcą je wybrać."},{"heading":"Przykład z warsztatu dla dwunastu dzieci","text":"Organizator ma 8 używanych kopert, 12 kartek i przybory do rysowania. Wspólnie przygotowują 12 kartek. Osiem osób może wybrać kopertę, a dla pozostałych animator przygotowuje z posiadanych skrawków opaski na złożone kartki. Jedna wspólna opowieść stanowi wariant dla dzieci, które wolą słuchać."},{"heading":"Sprawdź wynik po wykonaniu","text":"Lista materiałów pokrywa liczbę uczestników, miejsce jest przygotowane do sprzątnięcia, a dzieci mają dostępny wariant udziału. Możesz policzyć, ile przedmiotów wykorzystasz ponownie oraz co musisz zapewnić przed spotkaniem."}],"practice":{"title":"Ekologiczny Mikołaj: radość bez zbędnych zakupów","minutes":35,"visual":{"title":"Skąd wziąć materiały na wizytę","kind":"flow","entries":[{"label":"Sprawdź zasoby","detail":"Policz posiadane przybory, opakowania i rekwizyty."},{"label":"Wybierz to, co bezpieczne i potrzebne","detail":"Dopasuj materiały do wieku, czasu i liczby stanowisk."},{"label":"Przygotuj wariant wspólny","detail":"Zabawa, opowieść lub kartki z dostępnych materiałów."},{"label":"Zakończ z planem","detail":"Zachowaj sprawne rekwizyty na kolejne wydarzenie."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":17,"updated_at":"2026-11-11 06:20:18.367654+00","patch":{"learning":{"task":"W bezpiecznej symulacji przećwicz zatrzymanie grupy i opis zdarzenia przy stoliku. Podaj fikcyjnemu dyspozytorowi adres, stan osoby i dojście.","intro":"Przećwiczysz przerwanie wizyty, przekazanie odpowiedzialności i wezwanie właściwej pomocy przy nagłym zagrożeniu.","correct":0,"example":"Powiedz po imieniu, kto dzwoni po pomoc, kto zostaje z grupą i kto zwalnia dojście. Na próbie rolę dyspozytora odgrywa druga osoba.","options":["Przerwę wizytę, rozdzielę zadania przy dziecku i grupie oraz dopilnuję wezwania odpowiedniej pomocy i wolnego dojścia.","Poproszę pomocnika o przygotowanie krzesła, posadzę na nim dziecko i po chwili ustalę, czy wezwać pomoc.","Poproszę wszystkich dorosłych, żeby podeszli do dziecka, a następnie ogłoszę krótką przerwę w programie.","Powiem grupie, że pomocnik ma sprawdzić, co się stało. W tym czasie dokończę wręczanie paczek z drugiego końca sali."],"feedback":["Po poważnym upadku liczą się szybka reakcja, dostęp do miejsca zdarzenia i opieka nad grupą. Konkretne polecenia pozwalają wezwać pomoc i chronić pozostałych uczestników.","Przemieszczanie po upadku wymaga oceny sytuacji. Priorytetem są zabezpieczenie miejsca i wezwanie pomocy.","Tłok utrudnia dostęp, a grupa potrzebuje opiekuna. Warto od razu przerwać zabawę i rozdzielić role.","Zakończenie rozdawania może poczekać. Zatrzymaj program i zapewnij działanie odpowiednich osób."],"question":"Jak zareagujesz jako animator?","situation":"Po upadku na sali dziecko skarży się na silny ból i nie może wstać. Inne dzieci zaczynają zbierać się wokół, a pomocnik stoi przy drzwiach.","topic_kind":"authored_holiday_scenario","explanation":"Po poważnym upadku liczą się szybka reakcja, dostęp do miejsca zdarzenia i opieka nad grupą. Konkretne polecenia pozwalają wezwać pomoc i chronić pozostałych uczestników.","quiz_version":4,"quality_review":"editorial_pending"},"sections":[{"heading":"Ustal role i miejsce przed wizytą","text":"Sprawdź z gospodarzem, gdzie jest wyjście, gdzie znajduje się apteczka i kto pełni ustaloną rolę przy zdarzeniu. Zapisz dokładny adres z wejściem od właściwej ulicy. Animator powinien móc szybko przerwać zabawę. Wyznaczony opiekun pozostaje z dziećmi, a wskazana osoba prowadzi komunikację z pomocą."},{"heading":"Przerwij program i nazwij zadania","text":"Jeśli ktoś upadnie i potrzebuje pomocy, zatrzymaj aktywność, poproś opiekuna o zabezpieczenie grupy i zapewnij miejsce osobie udzielającej pomocy. Przy podejrzeniu nagłego zagrożenia zdrowia lub życia zadzwoń pod 112 albo wyznacz konkretną osobę do zadzwonienia i poproś o potwierdzenie. Podaj adres, powiedz, co widzisz, odpowiedz na pytania i postępuj według wskazówek dyspozytora."},{"heading":"Przykład z upadkiem na sali","text":"Dziecko upada przy stoliku, skarży się na silny ból i nie może wstać. Animator zatrzymuje zabawę. Wskazana osoba wzywa pomoc, a opiekun zatrzymuje pozostałe dzieci przy swoich miejscach. Pomocnik zwalnia dostęp i przygotowuje się do wskazania wejścia przyjeżdżającym służbom."},{"heading":"Sprawdź wynik po wykonaniu","text":"Umiesz jasno powiedzieć, kto pomaga dziecku, kto opiekuje się grupą i kto wzywa pomoc. Umiesz podać adres i fakty bez stawiania diagnozy. Wykonujesz tę próbę z symulowanym rozmówcą. Numer alarmowy służy do rzeczywistych zdarzeń."}],"practice":{"title":"Nagła sytuacja podczas wizyty","minutes":35,"visual":{"title":"Podział zadań po przerwaniu spotkania","kind":"flow","entries":[{"label":"Zatrzymaj zabawę","detail":"Wstrzymaj ruch grupy, zapewnij dostęp do miejsca zdarzenia."},{"label":"Wyznacz osoby","detail":"Opiekun pozostaje z grupą, a pomoc zajmuje się dzieckiem."},{"label":"Wezwij odpowiednią pomoc","detail":"Przy nagłym zagrożeniu dzwoń pod 112, podaj adres i fakty."},{"label":"Zapewnij dostęp","detail":"Kieruj się instrukcjami dyspozytora, wskaż służbom wejście."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":18,"updated_at":"2026-11-11 06:20:18.367654+00","patch":{"learning":{"task":"Przećwicz wizytę 20-minutową i 10-minutową ze stoperem. W drugim przebiegu dodaj rozbieżność etykiety i napisz zdanie informujące grupę o zmianie.","intro":"Przygotujesz wariant podstawowy i krótszy tak, by skrócenie wizyty nie zwiększało presji na dzieci i organizatorów.","correct":2,"example":"Można zrezygnować z dodatkowej piosenki i zostawić czas na wręczenie sprawdzonych paczek oraz spokojne pożegnanie.","options":["Przyspieszę wręczanie do 4 minut i zostawię wspólne zdjęcie, żeby ocalić większość programu.","Zacznę od piosenki i zdjęć. Paczki przekażę dopiero wtedy, jeśli wystarczy czasu.","Zaproponuję krótkie powitanie, spokojne wręczanie i zakończenie. Dodatkową piosenkę oraz zdjęcia skreślimy z tego wariantu.","Poproszę wszystkie dzieci o jednoczesny odbiór paczek, żeby zmieściły się też piosenka i zdjęcia."],"feedback":["Taki wariant zmniejsza realny czas wręczania o połowę bez próby ani nowego podziału pracy.","Krótszy wariant powinien od razu zabezpieczyć główną czynność i zakończenie.","Krótsza wizyta działa, jeśli zachowuje główny cel i realny czas potrzebny do spokojnego rozdania. Dodatki można zmienić wspólnie z gospodarzem.","Tłok utrudnia sprawdzenie przypisania i może zablokować przejście. Lepiej ograniczyć liczbę punktów programu."],"question":"Którą zmianę zaproponujesz gospodarzowi?","situation":"Z planowanych 20 minut zostało 10. Wręczenie paczek zajmuje w próbie 8 minut, a gospodarz prosi o zachowanie też piosenki i zdjęć.","topic_kind":"authored_holiday_scenario","explanation":"Krótsza wizyta działa, jeśli zachowuje główny cel i realny czas potrzebny do spokojnego rozdania. Dodatki można zmienić wspólnie z gospodarzem.","quiz_version":4,"quality_review":"editorial_pending"},"sections":[{"heading":"Ustal elementy, których potrzebuje każda wersja","text":"W każdym wariancie zostaw spokojne powitanie, udział na własnych zasadach, prawidłowe przekazanie paczek i bezpieczne zakończenie. Zapisz dodatki, które można wyłączyć bez reorganizacji grupy: wstęp muzyczny, dodatkowa zagadka albo dodatkowa seria zdjęć. Ustal z gospodarzem decyzję i sygnał do zmiany programu."},{"heading":"Rozpisz dwie rzeczywiste wersje","text":"Wersja 20-minutowa może obejmować 2 minuty powitania, 8 wręczania, 6 zabawy, 2 zdjęć dla chętnych i 2 zakończenia. Jeśli zostało 10 minut, zrób 1 minutę powitania, 8 spokojnego wręczania i 1 zakończenia. Jeżeli potrzebujecie dłuższego wręczania, uzgodnij z gospodarzem przejęcie części paczek po wizycie. Zaktualizuj osoby odpowiedzialne, zanim ogłosisz zmianę."},{"heading":"Przykład z opóźnionym wejściem","text":"Sala będzie dostępna 10 minut później. Animator, wychowawca i pomocnik wybierają krótszy plan. Pomocnik odkłada nierozpoznaną paczkę do sprawdzenia, a animator uprzedza grupę, że dziś będzie krótkie powitanie i odbiór paczek. Obie wersje przewidują odbiór przez opiekuna."},{"heading":"Sprawdź wynik po wykonaniu","text":"Oba warianty mieszczą się w pomiarze wykonanym podczas próby. Wiadomo, co usunięto i kto przejmie zadanie, które się nie zmieściło. Odmowa udziału, nieczytelna paczka i wolne wyjście mają obsługę również w krótszym wariancie."}],"practice":{"title":"Przygotowanie wizyty: próba i plan B","minutes":35,"visual":{"title":"Pełna wizyta i wizyta skrócona","kind":"comparison","entries":[{"label":"20 minut","detail":"2 powitanie + 8 paczki + 6 zabawa + 2 zdjęcia + 2 zakończenie."},{"label":"10 minut","detail":"1 powitanie + 8 paczki + 1 zakończenie."},{"label":"W obu wersjach","detail":"Zweryfikowana paczka, wolne przejście i dobrowolny udział."}]}},"content_revision":"2026-11-11"}},
{"lesson_no":19,"updated_at":"2026-11-11 06:20:18.367654+00","patch":{"learning":{"task":"Przeprowadź końcową próbę z kartą wizyty, dwiema zmianami organizacyjnymi i odmową zdjęcia. Oceń cztery kryteria i powtórz fragment wymagający poprawy.","intro":"Połączysz w jednym scenariuszu komunikację, paczki, organizację sali i reakcję na odmowę. Przygotujesz się do egzaminu po zaliczeniu lekcji.","correct":1,"example":"Jeżeli dziecko chce odebrać paczkę z opiekunką bez zdjęcia, umożliwiasz odbiór i planujesz fotografię chętnych albo scenografii.","options":["Poproszę o krótkie zdjęcie razem z opiekunką, bo wtedy dziecku może być wygodniej.","Umożliwię odbiór z opiekunką i miejsce poza kadrem. Z organizatorem ustalę zdjęcie chętnych lub ujęcie scenografii.","Zrobię jedno wspólne ujęcie, a później wytnę dziecko przed publikacją.","Wstrzymam wydawanie paczki, aż organizator uzgodni z opiekunką udział dziecka w zdjęciu."],"feedback":["Obecność opiekunki nie zmienia wyrażonej odmowy zdjęcia.","Udział w spotkaniu i odbiór paczki pozostają dostępne po odmowie. Organizator nadal może wybrać ujęcie zgodne z uzgodnionymi zasadami.","Odmowa obejmuje wykonanie zdjęcia. Wykadrowanie po fakcie tego nie rozwiązuje.","Odbiór paczki jest dostępny od razu. Sprawę zdjęcia można omówić osobno."],"question":"Jak zakończysz tę część wizyty i uzgodnisz zdjęcie z organizatorem?","situation":"Organizator mówi, że zdjęcie musi pokazywać całą grupę. Dziecko odmawia i chce odebrać paczkę z opiekunką. Pozostali czekają.","topic_kind":"authored_holiday_scenario","explanation":"Udział w spotkaniu i odbiór paczki pozostają dostępne po odmowie. Organizator nadal może wybrać ujęcie zgodne z uzgodnionymi zasadami.","quiz_version":4,"quality_review":"editorial_pending"},"sections":[{"heading":"Przygotuj kartę wizyty","text":"Zapisz miejsce, przewidywaną grupę, osoby odpowiedzialne i dwa warianty czasowe. Dodaj sposób powitania, oznaczania paczek oraz zgłaszania potrzeby przerwy. Opisz plan zdjęć i miejsce poza kadrem. Osobno zapisz, kto zarządza zmianą programu i kto reaguje na zdarzenie wymagające pomocy."},{"heading":"Sprawdź, jak plan działa pod presją","text":"Wybierz trzy zdarzenia z innych lekcji, np. nieczytelny kod, zbyt głośną muzykę i odmowę zdjęcia. Poproś drugą osobę, żeby wprowadziła je w nieznanej Ci kolejności. Zatrzymaj próbę, jeżeli dziecko w scenie nie ma już bezpiecznej opcji. Po próbie popraw kartę wizyty i powtórz najtrudniejszy fragment."},{"heading":"Przykład próby z nieobecnym pomocnikiem","text":"Organizator prosi o zdjęcie całej grupy, a pomocnik jest spóźniony. Animator ustala z wychowawcą przeniesienie zdjęcia na koniec i możliwość pozostania poza kadrem. Wychowawca wyznacza inną osobę do sprawdzenia paczek. Po rundzie zespół zapisuje obie zmiany na karcie."},{"heading":"Sprawdź wynik po wykonaniu","text":"Dziecko mogło odmówić zdjęcia i dostało paczkę. Opiekun i pomocnik mieli jasne zadania. Przejście pozostawało dostępne, a plan dało się zmienić. Po zaliczeniu tej i pozostałych lekcji otwórz egzamin w swoim kursie. Jego zaliczenie pozwala otrzymać dyplom ukończenia kursu."}],"practice":{"title":"Dyplom życzliwości: sprawdzian praktyczny","minutes":35,"visual":{"title":"Kryteria końcowej próby wizyty","kind":"comparison","entries":[{"label":"Wybór uczestnika","detail":"Rozmowa, kontakt i zdjęcie są dobrowolne."},{"label":"Sprawna organizacja","detail":"Opiekun i pomocnik znają role, a paczki są sprawdzone."},{"label":"Bezpieczny przebieg","detail":"Przejście jest wolne i wiadomo, jak przerwać spotkanie."},{"label":"Zmiana programu","detail":"Plan B zachowuje dostępność i zasady prywatności."}]}},"content_revision":"2026-11-11"}}]
$santa_data$::jsonb;
BEGIN
  IF jsonb_array_length(patches) <> 20 OR
     (SELECT count(*) FROM public.ta_lessons WHERE course_slug = 'swiety-mikolaj') <> 20 THEN
    RAISE EXCEPTION 'Unexpected Santa course lesson count';
  END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(patches) LOOP
    SELECT * INTO STRICT current_lesson
    FROM public.ta_lessons
    WHERE course_slug = 'swiety-mikolaj'
      AND lesson_no = (item->>'lesson_no')::integer
    FOR UPDATE;

    lesson_material := (current_lesson.material - 'illustration') || (item->'patch') ||
      jsonb_build_object('raw',
        jsonb_build_array(current_lesson.title_pl, item#>>'{patch,learning,intro}') ||
        (SELECT jsonb_agg(section->>'text' ORDER BY ordinal)
         FROM jsonb_array_elements(item#>'{patch,sections}') WITH ORDINALITY AS s(section, ordinal)));
    IF current_lesson.material = lesson_material THEN
      CONTINUE;
    END IF;
    IF current_lesson.updated_at IS DISTINCT FROM (item->>'updated_at')::timestamptz THEN
      RAISE EXCEPTION 'Santa lesson % changed since snapshot', current_lesson.lesson_no;
    END IF;

    UPDATE public.ta_lessons
    SET material = lesson_material, updated_at = now()
    WHERE course_slug = 'swiety-mikolaj' AND lesson_no = current_lesson.lesson_no;
  END LOOP;
END
$santa_update$;
